function Range({label,value,min=0,max=1,step=.01,onChange,unit='',format,disabled=false}:{label:string;value:number;min?:number;max?:number;step?:number;onChange:(value:number)=>void;unit?:string;format?:(n:number)=>string;disabled?:boolean}){return <label className={`range-control ${disabled?'disabled':''}`}><span>{label}<output>{format?format(value):`${value}${unit}`}</output></span><input aria-label={label} type="range" min={min} max={max} step={step} value={value} onChange={e=>onChange(Number(e.target.value))} disabled={disabled}/></label>;}
